export const CULTIVATION_REALM_BY_ID_V140 = new Map(CULTIVATION_REALMS_V140.map(x=>[x.id,x]));
export const CULTIVATION_REALM_BY_ORDER_V140 = new Map(CULTIVATION_REALMS_V140.map(x=>[x.order,x]));
export function cultivationRealmV140(idOrOrder){ const row=typeof idOrOrder==='number'?CULTIVATION_REALM_BY_ORDER_V140.get(idOrOrder):CULTIVATION_REALM_BY_ID_V140.get(idOrOrder); if(!row) throw new Error(`Unknown cultivation realm: ${idOrOrder}`); return row; }
export function isTribulationGateV140(order){ return order>=41 && order<=45; }
export function isMajorRealmGateV140(order){ if(order===0||order===9) return true; if(order>=13&&order<=113) return (order-13)%4===0; return false; }
export function retreatProgressPctPerHourV140(order){ return cultivationRealmV140(order).retreat3hProgressPct/3; }
export function requiredTuViV140(idOrOrder){ return cultivationRealmV140(idOrOrder).requiredTuVi; }
export function baseTuViPer15sV140(idOrOrder){ return cultivationRealmV140(idOrOrder).baseTuViPer15s; }

function clamp(v,min,max){ return Math.max(min,Math.min(max,Number(v)||0)); }
export function vietnamDayKeyV140(nowUnixMs=Date.now()){
  const shifted=new Date(Number(nowUnixMs)+7*3600_000);
  return `${shifted.getUTCFullYear()}-${String(shifted.getUTCMonth()+1).padStart(2,'0')}-${String(shifted.getUTCDate()).padStart(2,'0')}`;
}
export function previewRetreatBankV140(cultivation, nowUnixMs=Date.now()){
  const current=Math.max(0,Math.min(RETREAT_BANK_CAP_HOURS_V140,Number(cultivation?.retreatBankHours)||0));
  const today=vietnamDayKeyV140(nowUnixMs);
  const last=String(cultivation?.retreatBankDayKey||'');
  if(!last) return {bankHours:Math.min(RETREAT_BANK_CAP_HOURS_V140,Math.max(current,RETREAT_DAILY_BANK_HOURS_V140)),dayKey:today,accruedDays:0};
  const parse=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d);};
  const days=Math.max(0,Math.floor((parse(today)-parse(last))/86400000));
  return {bankHours:Math.min(RETREAT_BANK_CAP_HOURS_V140,current+days*RETREAT_DAILY_BANK_HOURS_V140),dayKey:today,accruedDays:days};
}
export function commitRetreatBankV140(cultivation, nowUnixMs=Date.now()){
  const p=previewRetreatBankV140(cultivation,nowUnixMs);
  cultivation.retreatBankHours=p.bankHours;
  cultivation.retreatBankDayKey=p.dayKey;
  return p;
}
export function cultivationRateV140(state, realmOrder){
  const row=cultivationRealmV140(realmOrder);
  const flat=Number(state?.cultivation?.flatTuViPer15s)||0;
  const configuredPct=Number(state?.cultivation?.baseTuViBonusPct)||0;
  const birthMultiplier=Math.max(.25,Math.min(8,Number(state?.inheritedOrigins?.['birth.cultivation.multiplier'])||1));
  const birthPct=(birthMultiplier-1)*100;
  const base=row.baseTuViPer15s;
  const perfectStage=Boolean(row.nextRealmId)&&CULTIVATION_REALMS_V140[row.order+1]?.majorRealmIndex!==row.majorRealmIndex;
  const reincarnationPct=additiveSelfCultivationPctR3(state,row.order,CULTIVATION_REALMS_V140,perfectStage);
  const fatePct=Math.max(0,Number(state?.character?.fateModifiersV4?.selfCultivationPct)||0);
  const spiritualRootPct=spiritualRootCultivationTotalBonusPctV145(resolveSpiritualRootStateV145(state?.character));
  const pct=configuredPct+birthPct+reincarnationPct+fatePct+spiritualRootPct;
  const final=Math.max(0,Math.round(base+flat+base*pct/100));
  return {baseTuViPer15s:base,flatTuViPer15s:flat,baseTuViBonusPct:pct,finalTuViPer15s:final,sources:[{id:'realm-base',label:`Nền ${row.name}`,kind:'base',value:base},...(flat?[{id:'flat',label:'Nguồn Tu Vi cố định',kind:'flat',value:flat}]:[]),...(birthPct?[{id:'birth',label:'Thiên phú / xuất thân',kind:'percent',value:birthPct}]:[]),...(configuredPct?[{id:'base-pct',label:'Nguồn % Tu Vi nền khác',kind:'percent',value:configuredPct}]:[]),...(reincarnationPct?[{id:'reincarnation-cultivation-r3',label:'Cây Luân Hồi · Tu Luyện',kind:'percent',value:reincarnationPct}]:[]),...(fatePct?[{id:'fate-v4',label:'Mệnh Cách',kind:'percent',value:fatePct}]:[]),...(spiritualRootPct?[{id:'spiritual-root-v145',label:'Linh Căn',kind:'percent',value:spiritualRootPct}]:[])]};
}
export function effectiveCultivationRequiredTuViV140(state,realmOrder){const row=cultivationRealmV140(realmOrder);const next=CULTIVATION_REALMS_V140[row.order+1];const majorGate=Boolean(row.nextRealmId)&&Boolean(next)&&next.majorRealmIndex!==row.majorRealmIndex;return effectiveMajorRequirementR3(state,row,majorGate);}
export function cultivationProgressV140(state, realmOrder){
  const row=cultivationRealmV140(realmOrder);
  const tuVi=Math.max(0,Number(state?.cultivation?.tuVi)||0);
  const required=effectiveCultivationRequiredTuViV140(state,realmOrder);
  return {tuVi,requiredTuVi:required,progressPct:required>0?Math.min(100,tuVi/required*100):100,ready:required===0||tuVi>=required};
}
export function addTuViV140(state, amount, realmOrder){
  const row=cultivationRealmV140(realmOrder);
  const before=Math.max(0,Number(state.cultivation.tuVi)||0);
  const cap=row.requiredTuVi>0?row.requiredTuVi:before;
  const after=row.requiredTuVi>0?Math.min(cap,before+Math.max(0,Number(amount)||0)):before;
  state.cultivation.tuVi=after;
  return {before,after,gained:after-before,requiredTuVi:row.requiredTuVi};
}
export function realtimeTuViGainV140(state, realmOrder, realSeconds){
  const rate=cultivationRateV140(state,realmOrder);
  const remainder=Math.max(0,Number(state.cultivation.commitRemainderSeconds)||0)+Math.max(0,Number(realSeconds)||0);
  const ticks=Math.floor(remainder/CULTIVATION_TICK_SECONDS_V140);
  state.cultivation.commitRemainderSeconds=remainder-ticks*CULTIVATION_TICK_SECONDS_V140;
  const applied=addTuViV140(state,ticks*rate.finalTuViPer15s,realmOrder);
  return {...applied,ticks,remainderSeconds:state.cultivation.commitRemainderSeconds,rate};
}
export function retreatRewardV140(state,realmOrder,hours){
  const row=cultivationRealmV140(realmOrder);
  const available=Math.max(0,Number(state.cultivation.retreatBankHours)||0);
  const requested=Math.max(0,Math.min(available,Number(hours)||0));
  if(requested<=0||row.requiredTuVi<=0) return {hoursUsed:0,gained:0,progressPct:0};
  const perHourPct=row.retreat3hProgressPct/3;
  const missing=Math.max(0,row.requiredTuVi-(Number(state.cultivation.tuVi)||0));
  const fateRetreatPct=Math.max(0,Number(state?.character?.fateModifiersV4?.retreatPct)||0);
  const rootRetreatPct=spiritualRootMeridianBonusesV145(resolveSpiritualRootStateV145(state?.character)).retreatBonusPct;
  const rawPerHour=row.requiredTuVi*perHourPct/100*(1+(fateRetreatPct+rootRetreatPct)/100);
  const neededHours=rawPerHour>0?missing/rawPerHour:0;
  const used=Math.min(requested,neededHours);
  const gain=Math.min(missing,rawPerHour*used);
  const applied=addTuViV140(state,gain,realmOrder);
  state.cultivation.retreatBankHours=Math.max(0,available-used);
  return {hoursUsed:used,gained:applied.gained,progressPct:row.requiredTuVi?applied.gained/row.requiredTuVi*100:0,bankHoursAfter:state.cultivation.retreatBankHours};
}
export function cleanCultivationStateV140(cultivation={}){
  return {tuVi:Math.max(0,Number(cultivation.tuVi)||0),commitRemainderSeconds:clamp(cultivation.commitRemainderSeconds,0,14.999999),retreatBankHours:clamp(cultivation.retreatBankHours||3,0,RETREAT_BANK_CAP_HOURS_V140),retreatBankDayKey:String(cultivation.retreatBankDayKey||''),reincarnationR3:cloneCultivationRuntimeR3(cultivation.reincarnationR3)};
}
